+// Encode encodes the LaxLoop.
+func (l *LaxLoop) Encode(w io.Writer) error {
+	e := &encoder{w: w}
+	l.encode(e)
+	return e.err
+}
+
+func (l *LaxLoop) encode(e *encoder) {
+	if l.numVertices > maxEncodedVertices {
+		e.err = fmt.Errorf("too many vertices (%d; max is %d)", l.numVertices, maxEncodedVertices)
+		return
+	}
+	e.writeInt8(encodingVersion)
+	e.writeUvarint(uint64(l.numVertices))
+	for _, v := range l.vertices {
+		e.writeFloat64(v.X)
+		e.writeFloat64(v.Y)
+		e.writeFloat64(v.Z)
+	}
+}
+
+// Decode decodes the LaxLoop.
+func (l *LaxLoop) Decode(r io.Reader) error {
+	d := &decoder{r: asByteReader(r)}
+	l.decode(d)
+	return d.err
+}
+
+func (l *LaxLoop) decode(d *decoder) {
+	version := d.readInt8()
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("can't decode version %d; my version: %d", version, encodingVersion)
+		return
+	}
+	n := d.readUvarint()
+	if d.err != nil {
+		return
+	}
+	if n > maxEncodedVertices {
+		d.err = fmt.Errorf("too many vertices (%d; max is %d)", n, maxEncodedVertices)
+		return
+	}
+	var pts []Point
+	if n > 0 {
+		pts = make([]Point, n)
+		for i := range pts {
+			pts[i].X = d.readFloat64()
+			pts[i].Y = d.readFloat64()
+			pts[i].Z = d.readFloat64()
+		}
+	}
+	if d.err != nil {
+		return
+	}
+	l.numVertices = int(n)
+	l.vertices = pts
+}
+
