+func TestShapeIndexEncodeDecodeGenericShape(t *testing.T) {
+	index := NewShapeIndex()
+	evEmpty := &edgeVectorShape{}
+	ev := edgeVectorShapeFromPoints(parsePoint("0:0"), parsePoint("1:1"))
+	ev.Add(parsePoint("2:2"), parsePoint("3:3"))
+	ev.Add(parsePoint("4:4"), parsePoint("5:5"))
+
+	id0 := index.Add(evEmpty)
+	id1 := index.Add(ev)
+
+	var buf bytes.Buffer
+	if err := index.Encode(&buf); err != nil {
+		t.Fatalf("Encode() error: %v", err)
+	}
+
+	decoded := NewShapeIndex()
+	if err := decoded.Decode(&buf); err != nil {
+		t.Fatalf("Decode() error: %v", err)
+	}
+
+	assertShapeEqual(t, decoded.Shape(id0), evEmpty)
+	assertShapeEqual(t, decoded.Shape(id1), ev)
+	assertShapeIndexEqual(t, decoded, index)
+	quadraticValidate(t, decoded)
+	testIteratorMethods(t, decoded)
+}
